(41293, 309, 352, '<td valign="top">The foreground lighting is vibrant, but the background is distracting.</td>', 'The foreground lighting is vibrant, but the background is distracting.', '2002-03-18 01:04:00.000000', NULL, 1),
(41294, 309, 27, '<td valign="top">if not for the background, I would have given this an 11</td>', 'if not for the background, I would have given this an 11', '2002-03-18 08:42:00.000000', NULL, 1),
(41295, 309, 142, '<td valign="top">Great techique and I get the feeling there is a story behind this image.</td>', 'Great techique and I get the feeling there is a story behind this image.', '2002-03-18 10:19:00.000000', NULL, 1),
(41296, 309, 324, '<td valign="top">Really great contrast between the cool tone of you and the vibrant warm red of the violin.  Beautifully done.</td>', 'Really great contrast between the cool tone of you and the vibrant warm red of the violin.  Beautifully done.', '2002-03-18 11:00:00.000000', NULL, 1),
(41297, 309, 173, '<td valign="top">Hard to tell how you incorporated the mirror for the challenge.</td>', 'Hard to tell how you incorporated the mirror for the challenge.', '2002-03-18 11:45:00.000000', NULL, 1),
(41298, 309, 436, '<td valign="top">pay more attention to distracting backgrounds</td>', 'pay more attention to distracting backgrounds', '2002-03-18 13:15:00.000000', NULL, 1),
