(41313, 311, 564, '<td valign="top">Nice use of a sillohette</td>', 'Nice use of a sillohette', '2002-03-18 00:31:00.000000', NULL, 1),
(41314, 311, 245, '<td valign="top">So little color used so effectively! The city in the distance is fantastic, you picked a great time of day to take this.</td>', 'So little color used so effectively! The city in the distance is fantastic, you picked a great time of day to take this.', '2002-03-18 01:22:00.000000', NULL, 1),
(41315, 311, 113, '<td valign="top">Wish I knew what you were saying, but the feeling comes through loud and clear.  Lovely picture.</td>', 'Wish I knew what you were saying, but the feeling comes through loud and clear.  Lovely picture.', '2002-03-18 03:34:00.000000', NULL, 1),
(41316, 311, 291, '<td valign="top">Excellent photo</td>', 'Excellent photo', '2002-03-18 10:47:00.000000', NULL, 1),
(41317, 311, 543, '<td valign="top">fantastic bit of perspective play!  your pose is interesting, too - introspective with a sense of motion.  i wouldn''t mind the composition a little more off-center - maybe 15% off the left added to the right so you''d get more of the dwarf city and get yourself onto a third.</td>', 'fantastic bit of perspective play!  your pose is interesting, too - introspective with a sense of motion.  i wouldn''t mind the composition a little more off-center - maybe 15% off the left added to the right so you''d get more of the dwarf city and get yourself onto a third.', '2002-03-18 11:24:00.000000', NULL, 1),
(41318, 311, 324, '<td valign="top">sweet background</td>', 'sweet background', '2002-03-18 11:46:00.000000', NULL, 1),
(41319, 311, 173, '<td valign="top">Hard to tell how you incorporated the mirror for the challenge, and the out stretched arm.</td>', 'Hard to tell how you incorporated the mirror for the challenge, and the out stretched arm.', '2002-03-18 11:47:00.000000', NULL, 1),
(41320, 311, 436, '<td valign="top">background strong, a bit more detail in your upper body &amp; clothing would make it a superb photo.</td>', 'background strong, a bit more detail in your upper body & clothing would make it a superb photo.', '2002-03-18 13:25:00.000000', NULL, 1),
(41321, 311, 279, '<td valign="top">Gorgeous.</td>', 'Gorgeous.', '2002-03-18 14:43:00.000000', NULL, 1),
