(41399, 321, 245, '<td valign="top">is that an evil camera strap I see?</td>', 'is that an evil camera strap I see?', '2002-03-18 01:26:00.000000', NULL, 1),
(41400, 321, 173, '<td valign="top">Hard to tell how you incorporated the mirror for the challenge, and the out stretched arm.</td>', 'Hard to tell how you incorporated the mirror for the challenge, and the out stretched arm.', '2002-03-18 11:40:00.000000', NULL, 1),
(41401, 321, 543, '<td valign="top">Here''s an image you can fall into.  The depth of field is huge.  Great colors, too.  The toes of your sneaks are a little burnt out, and I could do witout the camera strap, but what''s lacking technically is offset by the positives.  Nice work.</td>', 'Here''s an image you can fall into.  The depth of field is huge.  Great colors, too.  The toes of your sneaks are a little burnt out, and I could do witout the camera strap, but what''s lacking technically is offset by the positives.  Nice work.', '2002-03-18 11:56:00.000000', NULL, 1),
(41402, 321, 279, '<td valign="top">Like the color, and the grass, but the composition''s too banal.</td>', 'Like the color, and the grass, but the composition''s too banal.', '2002-03-18 14:46:00.000000', NULL, 1),
(41403, 321, 193, '<td valign="top">Very cute!  Excellent colour contrasts.  The black hoop (camera strap?) is distracting though.</td>', 'Very cute!  Excellent colour contrasts.  The black hoop (camera strap?) is distracting though.', '2002-03-18 15:20:00.000000', NULL, 1),
(41404, 321, 215, '<td valign="top">funny idea. get rid of the camera strap on the right and the picture would be that much better.</td>', 'funny idea. get rid of the camera strap on the right and the picture would be that much better.', '2002-03-20 08:17:00.000000', NULL, 1),
(41405, 321, 142, '<td valign="top">Nice interpretation.  And boy are you brave!</td>', 'Nice interpretation.  And boy are you brave!', '2002-03-20 16:52:00.000000', NULL, 1),
(41406, 321, 283, '<td valign="top">No you''re not that fat. Those pants are very slimming. Its different : ).</td>', 'No you''re not that fat. Those pants are very slimming. Its different : ).', '2002-03-20 19:50:00.000000', NULL, 1),
(41407, 321, 637, '<td valign="top">Where''s the beef?  Seriously, I like the idea and would like to see more of your tummy.</td>', 'Where''s the beef?  Seriously, I like the idea and would like to see more of your tummy.', '2002-03-20 22:20:00.000000', NULL, 1),
